	"--etag-compare": true,
	"--etag-save": true,
	"--expect100-timeout": true,
	"--haproxy-client-ip": true,
	"--noproxy": true,
	"--no-alpn": true, // actually no arg
	"--request-target": true,
	"--interface": true,
	"-Z": true,
	"--parallel-max": true,
	"--preproxy": true,
	"--service-name": true,
