func hasArg(flag string) bool {
	return flagsWithArg[flag]
}

type Args struct {
	CurlArgs    []string  // curl flags to pass through
	Method      string    // HTTP method
	URL         string    // URL
	Items       []Item    // request items
	Pretty      bool      // --pretty flag
	ShowCurl    bool      // --curl flag
	HasData     bool      // has -d flag (short form)
	HasForm     bool      // has -F/--form flag
}

type Item struct {
	Key   string
	Value string
	Type  ItemType
}

type ItemType int

const (
	ItemString  ItemType = iota // key=value -> JSON string
	ItemJSON                    // key:=value -> JSON raw
	ItemQuery                   // key==value -> query param
	ItemHeader                  // Key:value -> header
)

func parseArgs(rawArgs []string) Args {
	var result Args
	i := 0

	// Helper to check if a word could be a URL
	isURL := func(s string) bool {
		// Has :// or starts with : or contains . (domain)
		// Basically anything that could be a URL
		if strings.HasPrefix(s, "http://") || strings.HasPrefix(s, "https://") {
			return true
		}
		if strings.HasPrefix(s, ":") {
			return true
		}
		// Check if it looks like a host:port or domain
		if strings.Contains(s, ".") || strings.Contains(s, ":") {
			return true
		}
		return len(s) > 0 && !strings.HasPrefix(s, "-")
	}

	// Check if something is a method
	isMethod := func(s string) bool {
		return knownMethods[strings.ToUpper(s)]
	}

	// First pass: process special curlie flags and curl flags
	for i < len(rawArgs) {
		arg := rawArgs[i]

		// Curlie-specific flags
		if arg == "--pretty" {
			result.Pretty = true
			i++
			continue
		}
		if arg == "--curl" {
			result.ShowCurl = true
			i++
			continue
		}

		// Skip -i (intercepted by curlie)
		if arg == "-i" || arg == "--include" {
			if arg == "-i" {
				i++
				continue
			}
			// --include is passed through
		}

		// Check if it's a flag
		if strings.HasPrefix(arg, "-") {
			// Check if this flag has an argument
			flagName := arg
			// Handle -Xvalue style (combined flag+value)
			if len(arg) > 2 && !strings.HasPrefix(arg, "--") {
				flagName = arg[:2]
			}

			result.CurlArgs = append(result.CurlArgs, arg)

			// Check if -F or --form
			if flagName == "-F" || flagName == "--form" || flagName == "--form-string" {
				result.HasForm = true
			}

			// Check if -d (short form only)
			if flagName == "-d" {
				result.HasData = true
			}

			i++
			// If flag takes argument and it was not combined (like -Xvalue)
			if hasArg(flagName) && flagName == arg {
				// Next arg is the value
				if i < len(rawArgs) {
					result.CurlArgs = append(result.CurlArgs, rawArgs[i])
					i++
				}
			}
			continue
		}

		// Not a flag - could be METHOD or URL or item
		upper := strings.ToUpper(arg)
		if isMethod(arg) && result.URL == "" {
			result.Method = upper
			i++
			continue
		}

		// URL
		if result.URL == "" {
			result.URL = arg
			i++
			continue
		}

		// Request item
		item := parseItem(arg)
		result.Items = append(result.Items, item)
		i++
	}

	return result
}

func parseItem(s string) Item {
	// Check for == (query param)
	if idx := strings.Index(s, "=="); idx >= 0 {
		return Item{Key: s[:idx], Value: s[idx+2:], Type: ItemQuery}
	}
	// Check for := (raw JSON)
	if idx := strings.Index(s, ":="); idx >= 0 {
		return Item{Key: s[:idx], Value: s[idx+2:], Type: ItemJSON}
	}
	// Check for : (header) - but NOT :=
	if idx := strings.Index(s, ":"); idx >= 0 {
		// Make sure it's not :=
		return Item{Key: s[:idx], Value: s[idx+1:], Type: ItemHeader}
	}
	// Check for = (string body item)
	if idx := strings.Index(s, "="); idx >= 0 {
		return Item{Key: s[:idx], Value: s[idx+1:], Type: ItemString}
	}
	// Default: treat as header with no value
	return Item{Key: s, Value: "", Type: ItemHeader}
}

func displayURL(rawURL string) string {
	if strings.HasPrefix(rawURL, "http://") || strings.HasPrefix(rawURL, "https://") {
		return rawURL
	}
	return "http://" + rawURL
}

func curlURL(rawURL string, queryItems []Item) string {
	u := rawURL
	// Replace leading : with localhost:
	if strings.HasPrefix(u, ":") {
		u = "localhost" + u
	}

	// Append query items
	if len(queryItems) > 0 {
		sep := "?"
		if strings.Contains(u, "?") {
			sep = "&"
		}
		for _, item := range queryItems {
			u += sep + url.QueryEscape(item.Key) + "=" + url.QueryEscape(item.Value)
			sep = "&"
		}
	}
	return u
}

func buildBodyJSON(items []Item) ([]byte, error) {
	m := make(map[string]interface{})
	for _, item := range items {
		if item.Type == ItemString {
			m[item.Key] = item.Value
		} else if item.Type == ItemJSON {
			var v interface{}
			if err := json.Unmarshal([]byte(item.Value), &v); err != nil {
				return nil, err
			}
			m[item.Key] = v
		}
	}
	return json.Marshal(m)
}

func hasHeaderInCurlArgs(curlArgs []string, headerName string) bool {
	lower := strings.ToLower(headerName)
	for i, arg := range curlArgs {
		if arg == "-H" || arg == "--header" {
			if i+1 < len(curlArgs) {
				if strings.HasPrefix(strings.ToLower(curlArgs[i+1]), lower+":") {
					return true
				}
			}
		} else if strings.HasPrefix(arg, "-H") {
			val := arg[2:]
			if strings.HasPrefix(strings.ToLower(val), lower+":") {
				return true
			}
		}
	}
	return false
}

func buildCurlCommand(args Args) []string {
	var cmd []string

	// Add user curl args
	cmd = append(cmd, args.CurlArgs...)

	// Separate items by type
	var headerItems []Item
	var queryItems []Item
	var bodyItems []Item
	for _, item := range args.Items {
		switch item.Type {
		case ItemHeader:
			headerItems = append(headerItems, item)
		case ItemQuery:
			queryItems = append(queryItems, item)
		case ItemString, ItemJSON:
			bodyItems = append(bodyItems, item)
		}
	}

	// Add method
	if args.Method == "HEAD" {
		cmd = append(cmd, "-I")
	} else if args.Method != "" {
		cmd = append(cmd, "-X", args.Method)
	}

	// Add header items
	for _, item := range headerItems {
		hv := item.Key + ":" + item.Value
		cmd = append(cmd, "-H", hv)
	}

	// Add body
	if len(bodyItems) > 0 {
		body, err := buildBodyJSON(bodyItems)
		if err == nil {
			cmd = append(cmd, "-d", string(body))
		}
	}

	// Add URL
	urlStr := curlURL(args.URL, queryItems)
	cmd = append(cmd, urlStr)

	// Add default curl flags
	cmd = append(cmd, "-s", "-S")

	// Add -d@- if no body items and not -d flag
	if len(bodyItems) == 0 && !args.HasData && !args.HasForm {
		cmd = append(cmd, "-d@-")
	}

	// Check which default headers to add
	// Default Content-Type: application/json (unless user set it or has -F)
	addContentType := !args.HasForm
	if addContentType {
		// Check if user set Content-Type via -H or request items
		if hasHeaderInCurlArgs(args.CurlArgs, "content-type") {
			addContentType = false
		}
		for _, item := range headerItems {
			if strings.EqualFold(item.Key, "content-type") {
				addContentType = false
				break
			}
		}
	}

	// Default Accept
	addAccept := true
	if hasHeaderInCurlArgs(args.CurlArgs, "accept") {
		addAccept = false
	}
	for _, item := range headerItems {
		if strings.EqualFold(item.Key, "accept") {
			addAccept = false
			break
		}
	}

	if addContentType {
		cmd = append(cmd, "-H", "Content-Type: application/json")
	}
	if addAccept {
		cmd = append(cmd, "-H", "Accept: application/json, */*")
	}

	return cmd
}

func formatCurlCommandString(args []string) string {
	var parts []string
	for _, arg := range args {
		if strings.Contains(arg, " ") {
			parts = append(parts, `"`+arg+`"`)
		} else {
			parts = append(parts, arg)
		}
	}
	return "curl " + strings.Join(parts, " ")
}

// JSON pretty printer with ANSI colors
type jsonPrinter struct {
	w      io.Writer
	indent int
}

func writeJSON(w io.Writer, data []byte, depth int) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	writeJSONValue(w, dec, depth, false)
	fmt.Fprintf(w, "\n"+colorReset)
}

func writeJSONValue(w io.Writer, dec *json.Decoder, depth int, inArray bool) {
	tok, err := dec.Token()
	if err != nil {
		return
	}

	indent := strings.Repeat("    ", depth)

	switch v := tok.(type) {
	case json.Delim:
		switch v {
		case '{':
			fmt.Fprintf(w, colorWhite+"{")
			// Check if object is empty
			peeked := false
			_ = peeked
			writeJSONObject(w, dec, depth+1)
		case '[':
			fmt.Fprintf(w, colorWhite+"[")
			writeJSONArray(w, dec, depth+1)
		}
	case string:
		if inArray {
			fmt.Fprintf(w, colorBlue+`"`+escapeString(v)+`"`)
		} else {
			fmt.Fprintf(w, colorCyan+`"`+escapeString(v)+`"`)
		}
		_ = indent
	case json.Number:
		if inArray {
			fmt.Fprintf(w, "%s", v.String())
		} else {
			fmt.Fprintf(w, colorCyan+"%s", v.String())
		}
	case bool:
		boolStr := "false"
		if v {
			boolStr = "true"
		}
		if inArray {
			fmt.Fprintf(w, "%s", boolStr)
		} else {
			fmt.Fprintf(w, colorMagenta+"%s", boolStr)
		}
	case nil:
		if inArray {
			fmt.Fprintf(w, "null")
		} else {
			fmt.Fprintf(w, colorMagenta+"null")
		}
	}
}

func writeJSONObject(w io.Writer, dec *json.Decoder, depth int) {
	indent := strings.Repeat("    ", depth)
	parentIndent := strings.Repeat("    ", depth-1)

	fmt.Fprintf(w, "\n")

	first := true
	for dec.More() {
		if !first {
			// comma was already written
		}
		first = false

		// Read key
		keyTok, err := dec.Token()
		if err != nil {
			break
		}
		key, ok := keyTok.(string)
		if !ok {
			break
		}

		fmt.Fprintf(w, indent+colorBlue+`"`+escapeString(key)+`"`+colorWhite+": ")

		// Check if there are more items after this value
		// We need to know if we should add comma
		writeJSONValue(w, dec, depth, false)

		if dec.More() {
			fmt.Fprintf(w, colorWhite+",\n")
		} else {
			fmt.Fprintf(w, "\n")
		}
	}

	// Skip closing }
	dec.Token()

	if first {
		// Empty object - write blank indent line
		fmt.Fprintf(w, indent+"\n")
	}

	fmt.Fprintf(w, parentIndent+colorWhite+"}")
}

func writeJSONArray(w io.Writer, dec *json.Decoder, depth int) {
	indent := strings.Repeat("    ", depth)
	parentIndent := strings.Repeat("    ", depth-1)

	fmt.Fprintf(w, "\n")

	first := true
	for dec.More() {
		first = false
		fmt.Fprintf(w, indent)
		writeJSONValue(w, dec, depth, true)

		if dec.More() {
			fmt.Fprintf(w, colorWhite+",\n")
		} else {
			fmt.Fprintf(w, "\n")
		}
	}

	// Skip closing ]
	dec.Token()

	if first {
		// Empty array
		fmt.Fprintf(w, indent+"\n")
	}

	fmt.Fprintf(w, parentIndent+colorWhite+"]")
}

func escapeString(s string) string {
	b, _ := json.Marshal(s)
	// Remove surrounding quotes
	return string(b[1 : len(b)-1])
}

// Color a header line
func colorHeader(line string) string {
	line = strings.TrimRight(line, "\r")

	// Status line: HTTP/1.x NNN Message
	if strings.HasPrefix(line, "HTTP/") {
		parts := strings.SplitN(line, "/", 2)
		rest := parts[1]
		// rest = "1.x NNN Message"
		spaceIdx := strings.Index(rest, " ")
		if spaceIdx >= 0 {
			version := rest[:spaceIdx]
			statusRest := rest[spaceIdx:]
			// statusRest = " NNN Message"
			return colorBlue + "HTTP" + colorWhite + "/" + colorCyan + version + statusRest[:3+1] + colorYellow + statusRest[4:]
		}
		return colorBlue + "HTTP" + colorWhite + "/" + colorCyan + rest
	}

	// Regular header: Name: Value
	colonIdx := strings.Index(line, ":")
	if colonIdx >= 0 {
		name := line[:colonIdx+1]
		value := line[colonIdx+1:]
		return colorWhite + name + colorCyan + value
	}

	return line
}

func isJSONContentType(ct string) bool {
	ct = strings.ToLower(ct)
	return strings.Contains(ct, "application/json")
}

func run() int {
	args := parseArgs(os.Args[1:])

	if args.URL == "" {
		// Show help or error
		fmt.Fprintf(os.Stderr, "Usage: %s [options...] [METHOD] URL [REQUEST_ITEM [REQUEST_ITEM ...]]\n", os.Args[0])
		return 1
	}

	// Display URL on stderr
	fmt.Fprintf(os.Stderr, "%s\n", displayURL(args.URL))

	curlCmd := buildCurlCommand(args)

	if args.ShowCurl {
		fmt.Printf("%s\n", formatCurlCommandString(curlCmd))
		return 0
	}

	// Execute curl with -D - to capture headers
	internalCurlArgs := []string{"-D", "-"}
	internalCurlArgs = append(internalCurlArgs, curlCmd...)

	cmd := exec.Command("curl", internalCurlArgs...)
	cmd.Stdin = os.Stdin
	cmd.Stderr = os.Stderr

	stdout, err := cmd.StdoutPipe()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return 1
	}

	if err := cmd.Start(); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return 1
	}

	// Process curl output: headers first, then body
	reader := bufio.NewReader(stdout)

	// Read and process headers
	contentType := ""
	for {
		line, err := reader.ReadString('\n')
		if err != nil && len(line) == 0 {
			break
		}

		// Check for end of headers (blank line, possibly just \r\n)
		stripped := strings.TrimRight(line, "\r\n")
		if stripped == "" {
			if args.Pretty {
				fmt.Fprintf(os.Stderr, "\r\n")
			}
			break
		}

		// Extract content-type
		if strings.HasPrefix(strings.ToLower(stripped), "content-type:") {
			contentType = stripped[len("content-type:"):]
			contentType = strings.TrimSpace(contentType)
		}

		if args.Pretty {
			colored := colorHeader(stripped)
			fmt.Fprintf(os.Stderr, "%s\r"+colorReset+"\n", colored)
		}
	}

	// Read and process body
	body, err := io.ReadAll(reader)
	if err != nil && len(body) == 0 {
		// Error reading body
	}

	if args.Pretty && isJSONContentType(contentType) && len(body) > 0 {
		// Try to pretty-print JSON
		var v interface{}
		dec := json.NewDecoder(bytes.NewReader(body))
		dec.UseNumber()
		if err := dec.Decode(&v); err == nil {
			switch v.(type) {
			case map[string]interface{}, []interface{}:
				writeJSON(os.Stdout, body, 0)
				return cmd.Wait().ExitCode()
			}
		}
		// Fall through to raw output
	}

	os.Stdout.Write(body)

	if err := cmd.Wait(); err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			return exitErr.ExitCode()
		}
		return 1
	}
	return 0
}

func main() {
	os.Exit(run())
}
