	HasData  bool     // has -d flag (short form)
	HasForm  bool     // has -F/--form flag
}

type Item struct {
	Key   string
	Value string
	Type  ItemType
}

type ItemType int

const (
	ItemString ItemType = iota // key=value -> JSON string
	ItemJSON                   // key:=value -> JSON raw
	ItemQuery                  // key==value -> query param
	ItemHeader                 // Key:value -> header
)

func parseArgs(rawArgs []string) Args {
	var result Args
	i := 0

	// Check if something is a method
	isMethod := func(s string) bool {
		return knownMethods[strings.ToUpper(s)]
	}

	for i < len(rawArgs) {
		arg := rawArgs[i]

		// Curlie-specific flags
		if arg == "--pretty" {
			result.Pretty = true
			i++
			continue
		}
		if arg == "--curl" {
			result.ShowCurl = true
			i++
			continue
		}

		// Intercept -i (used internally by curlie, not passed to curl)
		if arg == "-i" {
			i++
			continue
		}

		// Check if it's a flag
		if strings.HasPrefix(arg, "-") {
			// Determine the flag name
			flagName := arg
			// Handle -Xvalue style (combined short flag+value like -XPOST)
			if len(arg) > 2 && !strings.HasPrefix(arg, "--") {
				flagName = arg[:2]
			}

			result.CurlArgs = append(result.CurlArgs, arg)

			// Check for form flags
			if flagName == "-F" || flagName == "--form" || flagName == "--form-string" {
				result.HasForm = true
			}

			// Check for -d short form (disables stdin passthrough)
			if flagName == "-d" {
				result.HasData = true
			}

			i++
			// If flag needs a separate argument value (not combined)
			if hasArg(flagName) && flagName == arg {
				if i < len(rawArgs) {
					result.CurlArgs = append(result.CurlArgs, rawArgs[i])
					i++
				}
			}
			continue
		}

		// Not a flag
		if result.URL == "" {
			// Could be METHOD or URL
			if isMethod(arg) {
				result.Method = strings.ToUpper(arg)
				i++
				continue
			}
			// It's the URL
			result.URL = arg
			i++
			continue
		}

		// Request item
		item := parseItem(arg)
		result.Items = append(result.Items, item)
		i++
	}

	return result
