		if result.URL == "" {
			if isMethod(arg) {
				result.Method = strings.ToUpper(arg)
				i++
				continue
			}
			result.URL = arg
			i++
			continue
		}

		item := parseItem(arg)
		result.Items = append(result.Items, item)
		i++
	}

