	HasData  bool
	HasForm  bool
	HasHelp  bool
	HasVerbose bool // -v or --verbose present
}

type Item struct {
	Key   string
	Value string
	Type  ItemType
}

type ItemType int

const (
	ItemString ItemType = iota
	ItemJSON
	ItemQuery
	ItemHeader
)

func processCombinedShortFlag(arg string) []string {
	if len(arg) <= 2 || strings.HasPrefix(arg, "--") {
		return []string{arg}
	}
	flagName := arg[:2]
	rest := arg[2:]

	if flagsWithArg[flagName] {
		return []string{flagName, rest}
	}

	result := []string{flagName}
	if len(rest) > 0 {
		result = append(result, processCombinedShortFlag("-"+rest)...)
	}
	return result
}

func parseArgs(rawArgs []string) ParsedArgs {
	var result ParsedArgs
	i := 0

	isMethod := func(s string) bool {
		return knownMethods[strings.ToUpper(s)]
	}

	for i < len(rawArgs) {
		arg := rawArgs[i]

		if arg == "--pretty" {
			result.Pretty = true
			i++
			continue
		}
		if arg == "--curl" {
			result.ShowCurl = true
			i++
			continue
		}
		if arg == "-i" {
			i++
			continue
		}

		if strings.HasPrefix(arg, "-") {
			if strings.HasPrefix(arg, "--") {
				if arg == "--form" {
					i++
					continue
				}

				result.CurlArgs = append(result.CurlArgs, arg)

				if arg == "-h" || arg == "--help" {
					result.HasHelp = true
					i++
					if i < len(rawArgs) && !strings.HasPrefix(rawArgs[i], "-") {
						result.CurlArgs = append(result.CurlArgs, rawArgs[i])
						i++
					}
					continue
				}
				if arg == "-v" || arg == "--verbose" {
					result.HasVerbose = true
				}

				i++
				if flagsWithArg[arg] && arg != "-h" && arg != "--help" {
					if i < len(rawArgs) && !strings.HasPrefix(rawArgs[i], "-") {
						result.CurlArgs = append(result.CurlArgs, rawArgs[i])
						i++
					}
				}
				continue
			}

			// Short flags
			if len(arg) == 2 {
				flagName := arg

				if flagName == "-F" {
					i++
					continue
				}
				if flagName == "-h" {
					result.HasHelp = true
					result.CurlArgs = append(result.CurlArgs, arg)
					i++
					if i < len(rawArgs) && !strings.HasPrefix(rawArgs[i], "-") {
						result.CurlArgs = append(result.CurlArgs, rawArgs[i])
						i++
					}
					continue
				}
				if flagName == "-v" {
					result.HasVerbose = true
				}

				result.CurlArgs = append(result.CurlArgs, arg)

				if flagName == "-d" {
					result.HasData = true
				}

				i++
				if flagsWithArg[flagName] {
					if i < len(rawArgs) && !strings.HasPrefix(rawArgs[i], "-") {
						result.CurlArgs = append(result.CurlArgs, rawArgs[i])
						i++
					}
				}
				continue
			}

			// Combined short flags
			flagName := arg[:2]

			if flagName == "-F" {
				result.HasForm = true
				result.CurlArgs = append(result.CurlArgs, "-F", arg[2:])
				i++
				continue
			}

			flags := processCombinedShortFlag(arg)
			result.CurlArgs = append(result.CurlArgs, flags...)

			if flagName == "-d" {
				result.HasData = true
			}
			if flagName == "-h" {
				result.HasHelp = true
			}
			if flagName == "-v" {
				result.HasVerbose = true
			}

			i++
			continue
		}

		if result.URL == "" {
			if isMethod(arg) {
				result.Method = strings.ToUpper(arg)
				i++
				continue
			}
			result.URL = arg
			i++
			continue
		}

		item := parseItem(arg)
		result.Items = append(result.Items, item)
		i++
	}

	return result
}

func parseItem(s string) Item {
	if idx := strings.Index(s, "=="); idx >= 0 {
		return Item{Key: s[:idx], Value: s[idx+2:], Type: ItemQuery}
	}
	if idx := strings.Index(s, ":="); idx >= 0 {
		return Item{Key: s[:idx], Value: s[idx+2:], Type: ItemJSON}
	}
	if idx := strings.Index(s, ":"); idx >= 0 {
		return Item{Key: s[:idx], Value: s[idx+1:], Type: ItemHeader}
	}
	if idx := strings.Index(s, "="); idx >= 0 {
		return Item{Key: s[:idx], Value: s[idx+1:], Type: ItemString}
	}
	return Item{Key: s, Value: "", Type: ItemHeader}
}

func displayURL(rawURL string, queryItems []Item) string {
	base := rawURL
	if !strings.HasPrefix(base, "http://") && !strings.HasPrefix(base, "https://") {
		base = "http://" + base
	}

	if len(queryItems) > 0 {
		sep := "?"
		if strings.Contains(base, "?") {
			sep = "&"
		}
		for _, item := range queryItems {
			base += sep + url.QueryEscape(item.Key) + "=" + url.QueryEscape(item.Value)
			sep = "&"
		}
	}
	return base
}

func curlURL(rawURL string, queryItems []Item) string {
	u := rawURL
	if strings.HasPrefix(u, ":") {
		u = "localhost" + u
	}

	if len(queryItems) > 0 {
		sep := "?"
		if strings.Contains(u, "?") {
			sep = "&"
		}
		for _, item := range queryItems {
			u += sep + url.QueryEscape(item.Key) + "=" + url.QueryEscape(item.Value)
			sep = "&"
		}
	}
	return u
}

func buildBodyJSON(items []Item) ([]byte, error) {
	m := make(map[string]interface{})
	for _, item := range items {
		if item.Type == ItemString {
			m[item.Key] = item.Value
		} else if item.Type == ItemJSON {
			var v interface{}
			if err := json.Unmarshal([]byte(item.Value), &v); err != nil {
				return nil, err
			}
			m[item.Key] = v
		}
	}
	return json.Marshal(m)
}

func hasHeaderInCurlArgs(curlArgs []string, headerName string) bool {
	lower := strings.ToLower(headerName)
	for i, arg := range curlArgs {
		if arg == "-H" || arg == "--header" {
			if i+1 < len(curlArgs) {
				if strings.HasPrefix(strings.ToLower(curlArgs[i+1]), lower+":") {
					return true
				}
			}
		} else if strings.HasPrefix(arg, "-H") && len(arg) > 2 {
			if strings.HasPrefix(strings.ToLower(arg[2:]), lower+":") {
				return true
			}
		}
	}
	return false
}

// hasVerboseInCurlArgs checks if -v or --verbose is in the curl args
func hasVerboseInCurlArgs(curlArgs []string) bool {
	for _, arg := range curlArgs {
		if arg == "-v" || arg == "--verbose" {
			return true
		}
		// Combined like -sv, -vs, etc.
		if len(arg) > 2 && !strings.HasPrefix(arg, "--") && strings.Contains(arg[1:], "v") {
			return true
		}
	}
	return false
}

func buildCurlCommand(args ParsedArgs) []string {
	var cmd []string
	cmd = append(cmd, args.CurlArgs...)

	var headerItems, queryItems, bodyItems []Item
	for _, item := range args.Items {
		switch item.Type {
		case ItemHeader:
			headerItems = append(headerItems, item)
		case ItemQuery:
			queryItems = append(queryItems, item)
		case ItemString, ItemJSON:
			bodyItems = append(bodyItems, item)
		}
	}

	if args.Method == "HEAD" {
		cmd = append(cmd, "-I")
	} else if args.Method != "" {
		cmd = append(cmd, "-X", args.Method)
	}

	for _, item := range headerItems {
		cmd = append(cmd, "-H", item.Key+":"+item.Value)
	}

	if len(bodyItems) > 0 {
		body, err := buildBodyJSON(bodyItems)
		if err == nil {
			cmd = append(cmd, "-d", string(body))
		}
	}

	urlStr := curlURL(args.URL, queryItems)
	cmd = append(cmd, urlStr)

	cmd = append(cmd, "-s", "-S")

	// Add -v if pretty mode and not already present
	if args.Pretty && !args.HasVerbose {
		cmd = append(cmd, "-v")
	}

	if !args.HasHelp && len(bodyItems) == 0 && !args.HasData {
		cmd = append(cmd, "-d@-")
	}

	addContentType := !args.HasForm && !args.HasHelp
	if addContentType {
		if hasHeaderInCurlArgs(args.CurlArgs, "content-type") {
			addContentType = false
		}
		for _, item := range headerItems {
			if strings.EqualFold(item.Key, "content-type") {
				addContentType = false
				break
			}
		}
	}

	addAccept := !args.HasHelp
	if addAccept {
		if hasHeaderInCurlArgs(args.CurlArgs, "accept") {
			addAccept = false
		}
		for _, item := range headerItems {
			if strings.EqualFold(item.Key, "accept") {
				addAccept = false
				break
			}
		}
	}

	if addContentType {
		cmd = append(cmd, "-H", "Content-Type: application/json")
	}
	if addAccept {
		cmd = append(cmd, "-H", "Accept: application/json, */*")
	}

	return cmd
}

func formatCurlCommandString(curlArgs []string) string {
	var parts []string
	for _, arg := range curlArgs {
		if strings.Contains(arg, " ") {
			parts = append(parts, `"`+arg+`"`)
		} else {
			parts = append(parts, arg)
		}
	}
	return "curl " + strings.Join(parts, " ")
}

func escapeString(s string) string {
	b, _ := json.Marshal(s)
	return string(b[1 : len(b)-1])
}

func writeJSON(w io.Writer, data []byte) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	writeValue(w, dec, 0, false)
	fmt.Fprintf(w, "\n"+colorReset)
}

func writeValue(w io.Writer, dec *json.Decoder, depth int, inArray bool) {
	tok, err := dec.Token()
	if err != nil {
		return
	}

	switch v := tok.(type) {
	case json.Delim:
		switch v {
		case '{':
			fmt.Fprintf(w, colorWhite+"{")
			writeObject(w, dec, depth+1)
		case '[':
			fmt.Fprintf(w, colorWhite+"[")
			writeArray(w, dec, depth+1)
		}
	case string:
		if inArray {
			fmt.Fprintf(w, colorBlue+`"`+escapeString(v)+`"`)
		} else {
			fmt.Fprintf(w, colorCyan+`"`+escapeString(v)+`"`)
		}
	case json.Number:
		if inArray {
			fmt.Fprintf(w, "%s", v.String())
		} else {
			fmt.Fprintf(w, colorCyan+"%s", v.String())
		}
	case bool:
		boolStr := "false"
		if v {
			boolStr = "true"
		}
		if inArray {
			fmt.Fprintf(w, "%s", boolStr)
		} else {
			fmt.Fprintf(w, colorMagenta+"%s", boolStr)
		}
	case nil:
		if inArray {
			fmt.Fprintf(w, "null")
		} else {
			fmt.Fprintf(w, colorMagenta+"null")
		}
	}
}

func writeObject(w io.Writer, dec *json.Decoder, depth int) {
	indent := strings.Repeat("    ", depth)
	parentIndent := strings.Repeat("    ", depth-1)
	fmt.Fprintf(w, "\n")

	empty := true
	for dec.More() {
		empty = false
		keyTok, err := dec.Token()
		if err != nil {
			break
		}
		key, ok := keyTok.(string)
		if !ok {
			break
		}
		fmt.Fprintf(w, indent+colorBlue+`"`+escapeString(key)+`"`+colorWhite+": ")
		writeValue(w, dec, depth, false)
		if dec.More() {
			fmt.Fprintf(w, colorWhite+",\n")
		} else {
			fmt.Fprintf(w, "\n")
		}
	}
	dec.Token()

	if empty {
		fmt.Fprintf(w, indent+"\n")
	}
	fmt.Fprintf(w, parentIndent+colorWhite+"}")
}

func writeArray(w io.Writer, dec *json.Decoder, depth int) {
	indent := strings.Repeat("    ", depth)
	parentIndent := strings.Repeat("    ", depth-1)
	fmt.Fprintf(w, "\n")

	empty := true
	for dec.More() {
		empty = false
		fmt.Fprintf(w, indent)
		writeValue(w, dec, depth, true)
		if dec.More() {
			fmt.Fprintf(w, colorWhite+",\n")
		} else {
			fmt.Fprintf(w, "\n")
		}
	}
	dec.Token()

	if empty {
		fmt.Fprintf(w, indent+"\n")
	}
	fmt.Fprintf(w, parentIndent+colorWhite+"]")
}

// colorHeaderLine applies color to an HTTP header line (response or request)
func colorHeaderLine(line string, pretty bool) string {
	line = strings.TrimRight(line, "\r")

	if !pretty {
		return line
	}

	// Status line: HTTP/x.x NNN Message
	if strings.HasPrefix(line, "HTTP/") {
		slashIdx := strings.Index(line, "/")
		if slashIdx >= 0 {
			rest := line[slashIdx+1:]
			spaceIdx := strings.Index(rest, " ")
			if spaceIdx >= 0 {
				version := rest[:spaceIdx]
				afterVersion := rest[spaceIdx+1:]
				codeEnd := strings.Index(afterVersion, " ")
				if codeEnd >= 0 {
					code := afterVersion[:codeEnd]
					msg := afterVersion[codeEnd:]
					return colorBlue + "HTTP" + colorWhite + "/" + colorCyan + version + " " + code + colorYellow + msg
				}
				return colorBlue + "HTTP" + colorWhite + "/" + colorCyan + rest
			}
		}
	}

	// Request line: METHOD PATH HTTP/VERSION
	// Detect: starts with an uppercase word, contains " HTTP/"
	if httpIdx := strings.LastIndex(line, " HTTP/"); httpIdx > 0 {
		prefix := line[:httpIdx] // "METHOD PATH"
		httpPart := line[httpIdx+1:] // "HTTP/VERSION"

		// Check if it looks like a request line (first word is uppercase)
		firstSpace := strings.Index(prefix, " ")
		if firstSpace > 0 {
			method := prefix[:firstSpace]
			path := prefix[firstSpace:]
			// Color: METHOD in blue, path in white, HTTP in blue, / in white, version in cyan
			slashIdx := strings.Index(httpPart, "/")
			if slashIdx >= 0 {
				version := httpPart[slashIdx+1:]
				return colorBlue + method + colorWhite + path + " " + colorBlue + "HTTP" + colorWhite + "/" + colorCyan + version
			}
		}
	}

	// Regular header: Name: Value
	colonIdx := strings.Index(line, ":")
	if colonIdx >= 0 {
		return colorWhite + line[:colonIdx+1] + colorCyan + line[colonIdx+1:]
	}

	return line
}

func isJSONContentType(ct string) bool {
	return strings.Contains(strings.ToLower(ct), "application/json")
}

func getExitCode(err error) int {
	if err == nil {
		return 0
	}
	if exitErr, ok := err.(*exec.ExitError); ok {
		if status, ok := exitErr.Sys().(syscall.WaitStatus); ok {
			return status.ExitStatus()
		}
		return 1
	}
	return 1
}

func injectHelpCategory(curlArgs []string) []string {
	result := make([]string, 0, len(curlArgs)+2)
	for i := 0; i < len(curlArgs); i++ {
		arg := curlArgs[i]
		result = append(result, arg)
		if arg == "-h" || arg == "--help" {
			if i+1 < len(curlArgs) && !strings.HasPrefix(curlArgs[i+1], "-") {
				// Category already follows
			} else {
				result = append(result, "")
			}
		}
	}
	return result
}

func runWithUsageReplacement(curlArgs []string) int {
	cmd := exec.Command("curl", curlArgs...)
	cmd.Stdin = os.Stdin
	cmd.Stderr = os.Stderr

	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return 1
	}

	if err := cmd.Start(); err != nil {
		return 1
	}

	reader := bufio.NewReader(stdout)
	firstLine := true
	for {
		line, err := reader.ReadString('\n')
		if len(line) > 0 {
			if firstLine {
				firstLine = false
				fmt.Printf("Usage: %s [options...] [METHOD] URL [REQUEST_ITEM [REQUEST_ITEM ...]]\n", os.Args[0])
			} else {
				fmt.Print(line)
			}
		}
		if err != nil {
			break
		}
	}

	return getExitCode(cmd.Wait())
}

// processVerboseLine processes a line from curl's verbose stderr output
// Returns the line to write to tool's stderr (with optional colors)
// pretty: whether to add ANSI colors
// Returns empty string for lines that should be skipped
func processVerboseLine(line string, pretty bool) string {
	// Trim trailing newline
	trimmed := strings.TrimRight(line, "\n")

	if strings.HasPrefix(trimmed, "* ") || trimmed == "*" {
		// Info line
		content := trimmed
		if pretty {
			content = strings.TrimRight(content, "\r")
			return colorDim + content + colorReset + "\n"
		}
		return content + "\n"
	}

	if strings.HasPrefix(trimmed, "> ") {
		// Request header (strip "> ")
		content := trimmed[2:]
		content = strings.TrimRight(content, "\r")
		if content == "" {
			// Blank request header line
			return "\r\n"
		}
		if pretty {
			return colorHeaderLine(content, true) + "\r" + colorReset + "\n"
		}
		return content + "\r\n"
	}

	if strings.HasPrefix(trimmed, "< ") {
		// Response header (strip "< ")
		content := trimmed[2:]
		content = strings.TrimRight(content, "\r")
		if content == "" {
			// Blank response header line (end of headers)
			return "\r\n"
		}
		if pretty {
			return colorHeaderLine(content, true) + "\r" + colorReset + "\n"
		}
		return content + "\r\n"
	}

	if trimmed == "<" || trimmed == ">" {
		// Bare delimiter
		return "\r\n"
	}

	// Other lines (like "{ [N bytes data]")
	// These are typically data size indicators, shown in dim
	if pretty {
		content := strings.TrimRight(trimmed, "\r")
		return colorDim + content + colorReset + "\n"
	}
	return trimmed + "\n"
}

func run() int {
	rawArgs := os.Args[1:]

	if len(rawArgs) == 0 {
		return runWithUsageReplacement([]string{"--help", "all"})
	}

	args := parseArgs(rawArgs)

	if args.URL == "" {
		if args.HasHelp {
			helpArgs := injectHelpCategory(args.CurlArgs)
			return runWithUsageReplacement(helpArgs)
		}
		if len(args.CurlArgs) == 0 {
			return runWithUsageReplacement([]string{"--help", "all"})
		}
		cmd := exec.Command("curl", args.CurlArgs...)
		cmd.Stdin = os.Stdin
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		if err := cmd.Run(); err != nil {
			return getExitCode(err)
		}
		return 0
	}

	var queryItems []Item
	for _, item := range args.Items {
		if item.Type == ItemQuery {
			queryItems = append(queryItems, item)
		}
	}

	fmt.Fprintf(os.Stderr, "%s\n", displayURL(args.URL, queryItems))

	curlCmd := buildCurlCommand(args)

	if args.ShowCurl {
		fmt.Printf("%s\n", formatCurlCommandString(curlCmd))
		return 0
	}

	if args.HasHelp {
		return runWithUsageReplacement(curlCmd)
	}

	// Determine if we need to process verbose output
	// We process when: --pretty is set OR user provided -v
	needVerboseProcessing := args.Pretty || args.HasVerbose

	if !needVerboseProcessing {
		// Simple passthrough: no header processing
		cmd := exec.Command("curl", curlCmd...)
		cmd.Stdin = os.Stdin
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		if err := cmd.Run(); err != nil {
			return getExitCode(err)
		}
		return 0
	}

	// Need to process curl's verbose stderr for headers
	// curl's stdout has the body, stderr has the verbose output
	cmd := exec.Command("curl", curlCmd...)
	cmd.Stdin = os.Stdin

	stderrPipe, err := cmd.StderrPipe()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return 1
	}
	stdoutPipe, err := cmd.StdoutPipe()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return 1
	}

	if err := cmd.Start(); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return 1
	}

	// Process stderr (verbose output) in a goroutine
	// Extract content-type from response headers
	contentTypeCh := make(chan string, 1)
	go func() {
		reader := bufio.NewReader(stderrPipe)
		contentType := ""
		seenResponse := false
		for {
			line, err := reader.ReadString('\n')
			if len(line) > 0 {
				// Check for content-type in response headers
				if strings.HasPrefix(line, "< ") {
					stripped := line[2:]
					stripped = strings.TrimRight(stripped, "\r\n")
					if strings.HasPrefix(strings.ToLower(stripped), "content-type:") {
						contentType = strings.TrimSpace(stripped[len("content-type:"):])
					}
					seenResponse = true
				}

				processed := processVerboseLine(line, args.Pretty)
				if processed != "" {
					fmt.Fprint(os.Stderr, processed)
				}
			}
			if err != nil {
				break
			}
		}
		_ = seenResponse
		contentTypeCh <- contentType
	}()

	// Read body from stdout
	bodyBuf, _ := io.ReadAll(stdoutPipe)

	contentType := <-contentTypeCh

	if args.Pretty && isJSONContentType(contentType) && len(bodyBuf) > 0 {
		trimmed := bytes.TrimSpace(bodyBuf)
		if len(trimmed) > 0 && (trimmed[0] == '{' || trimmed[0] == '[') {
			writeJSON(os.Stdout, bodyBuf)
			return getExitCode(cmd.Wait())
		}
	}

	os.Stdout.Write(bodyBuf)
	return getExitCode(cmd.Wait())
}

func main() {
	os.Exit(run())
}
