		content := strings.TrimRight(trimmed, "\r")
		if pretty {
			return colorDim + content + colorReset + "\n"
		}
		return content + "\n"
	}

	if strings.HasPrefix(trimmed, "> ") {
		if !showAll {
			return ""
		}
		content := trimmed[2:]
		content = strings.TrimRight(content, "\r")
		if content == "" {
			return "\r\n"
		}
		if pretty {
			return colorHeaderLine(content, true) + "\r" + colorReset + "\n"
		}
		return content + "\r\n"
	}

	if strings.HasPrefix(trimmed, "< ") {
		content := trimmed[2:]
		content = strings.TrimRight(content, "\r")
		if content == "" {
			return "\r\n"
		}
		if pretty {
			return colorHeaderLine(content, true) + "\r" + colorReset + "\n"
		}
		return content + "\r\n"
	}

	if trimmed == "<" || trimmed == ">" {
		if showAll {
			return "\r\n"
		}
		return ""
	}

	// Non-prefix lines
	if !showAll {
		return ""
	}

	// Check for "} [N bytes data]" - request body sent indicator
	if len(trimmed) > 0 && trimmed[0] == '}' && strings.Contains(trimmed, "[") && strings.Contains(trimmed, "bytes") {
		// Replace with actual request body
		if requestBody != "" && requestBody != "@-" {
			var buf bytes.Buffer
			outputRequestBody(&buf, requestBody, pretty)
			return buf.String()
		}
		return "\n\n"
	}

	// Check for "{ [N bytes data]" - response body received indicator  
	if len(trimmed) > 0 && trimmed[0] == '{' && strings.Contains(trimmed, "[") && strings.Contains(trimmed, "bytes") {
		return "\n\n"
	}

	// Other data lines (actual data being echoed in verbose)
	content := strings.TrimRight(trimmed, "\r")
	return content + "\n"
}

func run() int {
	rawArgs := os.Args[1:]

	if len(rawArgs) == 0 {
		return runWithUsageReplacement([]string{"--help", "all"})
	}

	args := parseArgs(rawArgs)

	if args.URL == "" {
		if args.HasHelp {
			helpArgs := injectHelpCategory(args.CurlArgs)
			return runWithUsageReplacement(helpArgs)
		}
		if len(args.CurlArgs) == 0 {
			return runWithUsageReplacement([]string{"--help", "all"})
		}
		cmd := exec.Command("curl", args.CurlArgs...)
		cmd.Stdin = os.Stdin
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		if err := cmd.Run(); err != nil {
			return getExitCode(err)
		}
		return 0
	}

	var queryItems []Item
	for _, item := range args.Items {
		if item.Type == ItemQuery {
			queryItems = append(queryItems, item)
		}
	}

	fmt.Fprintf(os.Stderr, "%s\n", displayURL(args.URL, queryItems))

	curlCmd := buildCurlCommand(args)

	if args.ShowCurl {
		fmt.Printf("%s\n", formatCurlCommandString(curlCmd))
		return 0
	}

	if args.HasHelp {
		return runWithUsageReplacement(curlCmd)
	}

	// Determine if we need verbose processing
	needVerboseProcessing := args.Pretty || args.HasVerbose

	if !needVerboseProcessing {
		// Simple passthrough
		cmd := exec.Command("curl", curlCmd...)
		cmd.Stdin = os.Stdin
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		if err := cmd.Run(); err != nil {
			return getExitCode(err)
		}
		return 0
	}

	// Find the request body from curlCmd
	requestBodyStr, isStdin := findRequestBody(curlCmd)

	// If body comes from stdin, read it and replace -d@- in curlCmd
	var stdinBody []byte
	if isStdin {
		var err error
		stdinBody, err = io.ReadAll(os.Stdin)
		if err == nil && len(stdinBody) > 0 {
			requestBodyStr = string(bytes.TrimRight(stdinBody, "\n"))
			// Replace -d@- with -d {body} in curlCmd
			for i, arg := range curlCmd {
				if arg == "@-" && i > 0 && curlCmd[i-1] == "-d" {
					curlCmd[i] = string(stdinBody)
					break
				}
			}
		}
	}

	// Run curl with verbose stderr processing
	cmd := exec.Command("curl", curlCmd...)
	if !isStdin || len(stdinBody) == 0 {
		cmd.Stdin = os.Stdin
	}

	stderrPipe, err := cmd.StderrPipe()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return 1
	}
	stdoutPipe, err := cmd.StdoutPipe()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return 1
	}

	if err := cmd.Start(); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return 1
	}

	// Process stderr in goroutine
	contentTypeCh := make(chan string, 1)
	go func() {
		reader := bufio.NewReader(stderrPipe)
		contentType := ""
		for {
			line, err := reader.ReadString('\n')
			if len(line) > 0 {
				// Extract content-type from response headers
				if strings.HasPrefix(line, "< ") {
					stripped := strings.TrimRight(line[2:], "\r\n")
					if strings.HasPrefix(strings.ToLower(stripped), "content-type:") {
						contentType = strings.TrimSpace(stripped[len("content-type:"):])
					}
				}

				processed := processVerboseLine(line, args.Pretty, args.HasVerbose, requestBodyStr)
				if processed != "" {
					fmt.Fprint(os.Stderr, processed)
				}
			}
			if err != nil {
				break
			}
		}
		contentTypeCh <- contentType
	}()

	// Read body from stdout
	bodyBuf, _ := io.ReadAll(stdoutPipe)

	contentType := <-contentTypeCh

	if args.Pretty && isJSONContentType(contentType) && len(bodyBuf) > 0 {
		trimmed := bytes.TrimSpace(bodyBuf)
		if len(trimmed) > 0 && (trimmed[0] == '{' || trimmed[0] == '[') {
			writeJSON(os.Stdout, bodyBuf)
			return getExitCode(cmd.Wait())
		}
	}

	os.Stdout.Write(bodyBuf)
	return getExitCode(cmd.Wait())
}

func main() {
	os.Exit(run())
}
